// Fechas objetivo (AAAA-MM-DD)
const en1 = $now.plus({ days: 1 }).toFormat('yyyy-MM-dd');
const en7 = $now.plus({ days: 7 }).toFormat('yyyy-MM-dd');

// El GET trae la lista; puede venir partida en varios items o en uno solo
const bruto = $input.all().map(i => i.json);
const lista = [];
for (const b of bruto) {
  if (Array.isArray(b)) { for (const x of b) lista.push(x); }
  else if (b && b.id) { lista.push(b); }
}

// Quien vence mañana o dentro de 7 días, con correo y aún activo
const candidatos = [];
for (const a of lista) {
  if (!a || !a.email || a.estado !== 'activo') continue;
  let dias = 0;
  if (a.fecha_limite === en1) dias = 1;
  else if (a.fecha_limite === en7) dias = 7;
  if (dias === 0) continue;
  candidatos.push({ a: a, dias: dias, clave: a.id + '-' + dias + 'd-' + a.fecha_limite });
}

// "Una sola vez": miramos lo que ya se envió en ejecuciones anteriores
const memoria = $getWorkflowStaticData('global');
if (!memoria.avisos) memoria.avisos = [];

const nuevos = [];
for (const c of candidatos) {
  if (memoria.avisos.indexOf(c.clave) !== -1) continue;  // ya enviado, lo saltamos
  nuevos.push(c);
}

return nuevos.map(c => {
  const a = c.a;
  const manana = c.dias === 1;
  const asunto = manana
    ? 'Mañana vence el plazo de tu apartado #' + a.id
    : 'En 7 días vence el plazo de tu apartado #' + a.id;
  const texto = 'Hola ' + a.cliente + ',\n\n'
    + (manana
        ? 'Te avisamos de que MAÑANA se cumple el plazo de tu apartado.\n\n'
        : 'Te avisamos de que en 7 DÍAS se cumple el plazo de tu apartado.\n\n')
    + 'Producto: ' + a.producto + '\n'
    + 'Fecha límite: ' + a.fecha_limite + '\n'
    + 'Te queda por pagar: ' + Number(a.pendiente).toFixed(2) + ' EUR\n\n'
    + 'Si ya has pagado, disculpa las molestias.\n\n'
    + 'Zapatería Paso Firme';
  return {
    json: {
      clave: c.clave,
      id: a.id,
      cliente: a.cliente,
      email: a.email,
      producto: a.producto,
      pendiente: a.pendiente,
      fecha_limite: a.fecha_limite,
      dias: c.dias,
      asunto: asunto,
      texto: texto
    }
  };
});

const memoria = $getWorkflowStaticData('global');
if (!memoria.avisos) memoria.avisos = [];

return $input.all().map((item, i) => {
  const clave = $('Recordatorios de hoy').itemMatching(i).json.clave;
  if (clave && memoria.avisos.indexOf(clave) === -1) {
    memoria.avisos.push(clave);
  }
  return { json: { clave: clave, ya_enviado: true } };
});

// La app es la fuente de verdad: aquí solo filtramos.
// El GET ya trae estado=activo, así que solo miramos la fecha límite.
const hoy = $now.toFormat('yyyy-MM-dd');

// El GET puede venir partido en varios items o en uno solo
const bruto = $input.all().map(i => i.json);
const lista = [];
for (const b of bruto) {
  if (Array.isArray(b)) { for (const x of b) lista.push(x); }
  else if (b && b.id) { lista.push(b); }
}

return lista
  .filter(a => a && a.fecha_limite && a.fecha_limite < hoy)
  .map(a => ({ json: a }));

// Se ejecuta UNA vez y recoge todos los vencidos del POST
const items = $input.all().map(i => i.json);

const eur = (n) => {
  const num = Number(n);
  if (!Number.isFinite(num)) return '(sin importe)';
  const [ent, dec] = num.toFixed(2).split('.');
  return ent.replace(/\B(?=(\d{3})+(?!\d))/g, '.') + ',' + dec + ' €';
};

const fecha = (iso) => {
  const m = String(iso || '').match(/^(\d{4})-(\d{2})-(\d{2})/);
  return m ? m[3] + '/' + m[2] + '/' + m[1] : String(iso || '');
};

const avisos = [];
for (const v of items) {
  const a = v.apartado, vale = v.vale;
  if (!a || !vale) continue;
  if (!a.email) continue;   // sin correo: solo sale en la lista de Marisa

  avisos.push({ json: {
    id: a.id,
    email: a.email,
    asunto: 'Tu apartado #' + a.id + ' ha vencido · Vale ' + vale.codigo,
    texto:
      'Hola ' + a.cliente + ',\n\n' +
      'Se ha cumplido el plazo de tu apartado y los zapatos vuelven a la venta.\n' +
      'Lo que habías abonado se convierte en un VALE DE COMPRA, para que no pierdas tu dinero.\n\n' +
      'Código del vale : ' + vale.codigo + '\n' +
      'Importe         : ' + eur(vale.importe) + '\n' +
      'Fecha           : ' + fecha(vale.fecha) + '\n\n' +
      'Puedes usarlo en tu próxima compra en Zapatería Paso Firme.\n\n' +
      'Apartado #' + a.id + ' · ' + a.producto + '\n\n' +
      'Zapatería Paso Firme'
  }});
}
return avisos;

const items = $input.all().map(i => i.json);

const eur = (n) => {
  const num = Number(n);
  if (!Number.isFinite(num)) return '(sin importe)';
  const [ent, dec] = num.toFixed(2).split('.');
  return ent.replace(/\B(?=(\d{3})+(?!\d))/g, '.') + ',' + dec + ' €';
};

let total = 0;
let n = 0;
const lineas = [];

for (const v of items) {
  const a = v.apartado, vale = v.vale;
  if (!a || !vale) continue;
  n++;
  total += Number(vale.importe) || 0;
  lineas.push(
    '· #' + a.id + '  ' + a.cliente + ' — ' + a.producto +
    (a.talla ? ' (talla ' + a.talla + ')' : '') +
    '\n     Vale ' + vale.codigo + ' por ' + eur(vale.importe) +
    (a.email ? '' : '   ⚠ SIN CORREO: avisar a mano')
  );
}

return [{ json: {
  asunto: 'Vencidos hoy: ' + n + ' apartado(s) · ' + eur(total) + ' en vales',
  texto:
    'Hola Marisa,\n\n' +
    'Hoy se han vencido ' + n + ' apartado(s). Estos zapatos vuelven a la venta:\n\n' +
    lineas.join('\n\n') + '\n\n' +
    'Total en vales: ' + eur(total) + '\n\n' +
    'Zapatería Paso Firme'
}}];
